var tokens = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
if (tokens.Length != 2) Environment.Exit(1);
if (!int.TryParse(tokens[0], out var initial)) Environment.Exit(1);
if (!int.TryParse(tokens[1], out var amount)) Environment.Exit(1);
if (initial < 0 || initial > 1000000) Environment.Exit(1);
var account = new Account(initial);
if (account.TryWithdraw(amount)) Console.WriteLine(account.GetBalance());
else Console.WriteLine("DENIED");

class Account
{
    private int _balance;

    public Account(int initialBalance) => _balance = initialBalance;

    public int GetBalance() => _balance;

    public bool TryWithdraw(int amount)
    {
        if (amount < 0 || amount > _balance) return false;
        _balance -= amount;
        return true;
    }
}
